"""Generate queue/hard100.jsonl: 100 harder lemmas in three tiers (Mathlib).

Every statement is true. `known` says whether we expect a close match in
Mathlib (the run's --library-check measures this for real)."""
import json
from pathlib import Path

E, S, O = "exercise", "stretch", "olympiad"
L = []
def add(tier, id_, stmt, note, known=False):
    L.append({"id": id_, "name": id_, "requires": "mathlib", "tier": tier,
              "preamble": "", "statement": stmt, "notes": note,
              "expected_in_mathlib": known})

# ---------- exercise (25): standard textbook facts ----------
add(E, "e_sum_odd", "(n : ℕ) : ∑ i ∈ range n, (2 * i + 1) = n ^ 2", "Sum of first n odd numbers.", True)
add(E, "e_sum_sq", "(n : ℕ) : 6 * ∑ i ∈ range (n + 1), i ^ 2 = n * (n + 1) * (2 * n + 1)", "Sum of squares.")
add(E, "e_geom_two", "(n : ℕ) : ∑ i ∈ range n, 2 ^ i = 2 ^ n - 1", "Geometric sum, natural subtraction.", True)
add(E, "e_seven_dvd", "(n : ℕ) : 7 ∣ 8 ^ n - 1", "8 ≡ 1 mod 7.")
add(E, "e_eleven_dvd", "(n : ℕ) : 11 ∣ 10 ^ (2 * n) - 1", "100 ≡ 1 mod 11.")
add(E, "e_bernoulli", "(x : ℝ) (hx : -1 ≤ x) (n : ℕ) : 1 + n * x ≤ (1 + x) ^ n", "Bernoulli's inequality.", True)
add(E, "e_two_ab", "(a b : ℝ) : 2 * a * b ≤ a ^ 2 + b ^ 2", "Two-term AM-GM.", True)
add(E, "e_three_sq", "(a b c : ℝ) : a * b + b * c + c * a ≤ a ^ 2 + b ^ 2 + c ^ 2", "Sum of squared differences.")
add(E, "e_cauchy2", "(a b c d : ℝ) : (a * c + b * d) ^ 2 ≤ (a ^ 2 + b ^ 2) * (c ^ 2 + d ^ 2)", "Cauchy-Schwarz, 2 terms.")
add(E, "e_even_sq", "(n : ℤ) (h : Even (n ^ 2)) : Even n", "Parity of squares.", True)
add(E, "e_sqrt2_irr", ": Irrational (Real.sqrt 2)", "√2 is irrational.", True)
add(E, "e_gcd_consec", "(n : ℕ) : Nat.gcd n (n + 1) = 1", "Consecutive numbers are coprime.", True)
add(E, "e_gcd_fib", "(n : ℕ) : Nat.gcd (Nat.fib n) (Nat.fib (n + 1)) = 1", "Consecutive Fibonacci numbers are coprime.", True)
add(E, "e_choose_sum", "(n : ℕ) : ∑ k ∈ range (n + 1), n.choose k = 2 ^ n", "Row sum of Pascal's triangle.", True)
add(E, "e_quad_roots", "(x : ℝ) (h : x ^ 2 - 5 * x + 6 = 0) : x = 2 ∨ x = 3", "Factor a quadratic.")
add(E, "e_abs_tri", "(a b : ℝ) : |a + b| ≤ |a| + |b|", "Triangle inequality.", True)
add(E, "e_inj_comp", "{α β γ : Type*} (f : α → β) (g : β → γ) (hf : Function.Injective f) (hg : Function.Injective g) : Function.Injective (g ∘ f)", "Composition of injections.", True)
add(E, "e_set_distrib", "{α : Type*} (A B C : Set α) : A ∩ (B ∪ C) = (A ∩ B) ∪ (A ∩ C)", "Set distributivity.", True)
add(E, "e_lin_sys", "(x y : ℝ) (h1 : 2 * x + 3 * y = 7) (h2 : x - y = 1) : x = 2 ∧ y = 1", "2x2 linear system.")
add(E, "e_digits_mod9", "(n : ℕ) : n % 9 = (Nat.digits 10 n).sum % 9", "Casting out nines.", True)
add(E, "e_prime_two_or_odd", "(p : ℕ) (hp : p.Prime) : p = 2 ∨ Odd p", "Primes other than 2 are odd.", True)
add(E, "e_pow5_last_digit", "(n : ℕ) : n ^ 5 % 10 = n % 10", "n^5 and n end in the same digit.")
add(E, "e_cube_mod9", "(n : ℤ) : n ^ 3 % 9 = 0 ∨ n ^ 3 % 9 = 1 ∨ n ^ 3 % 9 = 8", "Cubes mod 9.")
add(E, "e_sum_recip", "(n : ℕ) : ∑ k ∈ range n, (1 : ℚ) / (((k : ℚ) + 1) * ((k : ℚ) + 2)) = (n : ℚ) / ((n : ℚ) + 1)", "Telescoping sum.")
add(E, "e_two_pow_le_fact", "(n : ℕ) : 2 ^ n ≤ Nat.factorial (n + 1)", "Induction on factorial.")

# ---------- stretch (39): multi-step proofs ----------
add(S, "s_sophie_germain", "(n : ℕ) (h : 2 ≤ n) : ¬ Nat.Prime (n ^ 4 + 4)", "n^4+4 = (n²+2n+2)(n²-2n+2).")
add(S, "s_sum_k_fact", "(n : ℕ) : ∑ k ∈ range n, k * Nat.factorial k = Nat.factorial n - 1", "Telescoping with factorials.")
add(S, "s_amgm4", "(a b c d : ℝ) : 4 * a * b * c * d ≤ a ^ 4 + b ^ 4 + c ^ 4 + d ^ 4", "Four-term AM-GM, quartic form.")
add(S, "s_schur", "(a b c : ℝ) (ha : 0 ≤ a) (hb : 0 ≤ b) (hc : 0 ≤ c) : 0 ≤ a * (a - b) * (a - c) + b * (b - a) * (b - c) + c * (c - a) * (c - b)", "Schur's inequality t=1; needs WLOG ordering.")
add(S, "s_cauchy3", "(a b c x y z : ℝ) : (a * x + b * y + c * z) ^ 2 ≤ (a ^ 2 + b ^ 2 + c ^ 2) * (x ^ 2 + y ^ 2 + z ^ 2)", "Cauchy-Schwarz, 3 terms.")
add(S, "s_recip_sum", "(a b : ℝ) (ha : 0 < a) (hb : 0 < b) (h : a + b = 1) : 4 ≤ 1 / a + 1 / b", "HM-AM with a constraint.")
add(S, "s_recip_sq_sum", "(a b : ℝ) (ha : 0 < a) (hb : 0 < b) (h : a + b = 1) : 25 / 2 ≤ (a + 1 / a) ^ 2 + (b + 1 / b) ^ 2", "Classic constrained inequality.")
add(S, "s_harmonic_pow2", "(n : ℕ) : 1 + (n : ℝ) / 2 ≤ ∑ k ∈ range (2 ^ n), (1 : ℝ) / ((k : ℝ) + 1)", "Oresme's bound H_{2^n} ≥ 1 + n/2.")
add(S, "s_sqrt_diff", "(x : ℝ) (hx : 0 < x) : Real.sqrt (x + 1) - Real.sqrt x ≤ 1 / (2 * Real.sqrt x)", "Rationalise the difference of roots.")
add(S, "s_cassini", "(n : ℕ) : (Nat.fib (n + 1) : ℤ) ^ 2 - (Nat.fib n : ℤ) * (Nat.fib (n + 2) : ℤ) = (-1) ^ n", "Cassini's identity.", True)
add(S, "s_fib_add", "(m n : ℕ) : Nat.fib (m + n + 1) = Nat.fib m * Nat.fib n + Nat.fib (m + 1) * Nat.fib (n + 1)", "Fibonacci addition formula.", True)
add(S, "s_fib_three_even", "(n : ℕ) : Even (Nat.fib (3 * n))", "Every third Fibonacci number is even.")
add(S, "s_fib_sq_sum", "(n : ℕ) : ∑ k ∈ range (n + 1), Nat.fib k ^ 2 = Nat.fib n * Nat.fib (n + 1)", "Sum of squared Fibonacci numbers.")
add(S, "s_odd_cubes", "(n : ℕ) : ∑ i ∈ range n, (2 * i + 1) ^ 3 = n ^ 2 * (2 * n ^ 2 - 1)", "Sum of odd cubes.")
add(S, "s_prime_sq_24", "(p : ℕ) (hp : p.Prime) (h5 : 5 ≤ p) : 24 ∣ p ^ 2 - 1", "p² ≡ 1 mod 24 for primes ≥ 5.")
add(S, "s_euler_poly", ": ¬ ∀ n : ℕ, Nat.Prime (n ^ 2 + n + 41)", "Euler's polynomial fails at n = 40.")
add(S, "s_two_sq_mod4", "(x y : ℤ) : (x ^ 2 + y ^ 2) % 4 ≠ 3", "Sums of two squares mod 4.")
add(S, "s_three_sq_mod8", "(x y z : ℤ) : (x ^ 2 + y ^ 2 + z ^ 2) % 8 ≠ 7", "Sums of three squares mod 8.")
add(S, "s_cubes_four", ": ¬ ∃ x y : ℤ, x ^ 3 + y ^ 3 = 4", "Cubes mod 9.")
add(S, "s_sqrt3_irr", ": Irrational (Real.sqrt 3)", "√3 is irrational.", True)
add(S, "s_sqrt2_add_sqrt3", ": Irrational (Real.sqrt 2 + Real.sqrt 3)", "Square to reduce to √6.")
add(S, "s_log_lower", "(x : ℝ) (hx : 0 < x) : 1 - 1 / x ≤ Real.log x", "From log y ≤ y - 1 at y = 1/x.")
add(S, "s_exp_quad", "(x : ℝ) (hx : 0 ≤ x) : 1 + x + x ^ 2 / 2 ≤ Real.exp x", "Taylor lower bound.", True)
add(S, "s_tendsto_recip", ": Filter.Tendsto (fun n : ℕ => (1 : ℝ) / ((n : ℝ) + 1)) Filter.atTop (nhds 0)", "1/(n+1) → 0.", True)
add(S, "s_tendsto_ratio", ": Filter.Tendsto (fun n : ℕ => ((n : ℝ) + 1) / (2 * (n : ℝ) + 3)) Filter.atTop (nhds (1 / 2))", "Limit of a rational sequence.")
add(S, "s_deriv_cubic", ": deriv (fun x : ℝ => x ^ 3 + 2 * x) 1 = 5", "Compute a derivative.")
add(S, "s_ivt_root", ": ∃ x : ℝ, 0 ≤ x ∧ x ≤ 1 ∧ x ^ 3 + x - 1 = 0", "Intermediate value theorem.")
add(S, "s_strictmono_cubic", ": StrictMono (fun x : ℝ => x ^ 3 + x)", "Monotonicity of x³ + x.")
add(S, "s_additive_odd", "(f : ℝ → ℝ) (h : ∀ x y, f (x + y) = f x + f y) : f 0 = 0 ∧ ∀ x, f (-x) = -f x", "Cauchy equation basics.")
add(S, "s_func_solve", "(f : ℝ → ℝ) (h : ∀ x, f x + 2 * f (1 - x) = x ^ 2) : ∀ x, f x = (x ^ 2 - 4 * x + 2) / 3", "Substitute x ↦ 1 - x.")
add(S, "s_group_exp2", "{G : Type*} [Group G] (h : ∀ g : G, g * g = 1) (a b : G) : a * b = b * a", "Exponent-2 groups are abelian.")
add(S, "s_boolean_ring", "{R : Type*} [Ring R] (h : ∀ x : R, x * x = x) (a : R) : a + a = 0", "Boolean rings have characteristic 2.")
add(S, "s_cayley_hamilton2", "(A : Matrix (Fin 2) (Fin 2) ℝ) : A * A - Matrix.trace A • A + Matrix.det A • (1 : Matrix (Fin 2) (Fin 2) ℝ) = 0", "Cayley-Hamilton for 2x2.")
add(S, "s_pigeonhole", "(f : Fin 5 → Fin 4) : ∃ i j, i ≠ j ∧ f i = f j", "Pigeonhole.", True)
add(S, "s_pairs_choose", "(n : ℕ) : ((range n ×ˢ range n).filter (fun p => p.1 < p.2)).card = n.choose 2", "Count ordered pairs.")
add(S, "s_divisors_360", ": (Nat.divisors 360).card = 24", "Computation.")
add(S, "s_totient_1000", ": Nat.totient 1000 = 400", "Computation.")
add(S, "s_pow_mod_1000", ": 2 ^ 2026 % 1000 = 864", "Computation (modular exponent).")
add(S, "s_digit_sum_2_100", ": (Nat.digits 10 (2 ^ 100)).sum = 115", "Computation.")

# ---------- olympiad (36): competition style, mostly not in Mathlib ----------
add(O, "o_amgm_prod_one", "(a b c : ℝ) (ha : 0 < a) (hb : 0 < b) (hc : 0 < c) (h : a * b * c = 1) : 3 ≤ a + b + c", "AM-GM with abc = 1.")
add(O, "o_pairwise_8abc", "(a b c : ℝ) (ha : 0 < a) (hb : 0 < b) (hc : 0 < c) : 8 * a * b * c ≤ (a + b) * (b + c) * (c + a)", "Product of pairwise AM-GM.")
add(O, "o_power_mean3", "(a b : ℝ) (ha : 0 ≤ a) (hb : 0 ≤ b) : ((a + b) / 2) ^ 3 ≤ (a ^ 3 + b ^ 3) / 2", "Power mean, cubic.")
add(O, "o_sum3_pairs", "(x y z : ℝ) (h : x + y + z = 3) : x * y + y * z + z * x ≤ 3", "Fixed sum bounds pairwise products.")
add(O, "o_sqrt_sum", "(a b : ℝ) (ha : 0 ≤ a) (hb : 0 ≤ b) : Real.sqrt a + Real.sqrt b ≤ Real.sqrt (2 * (a + b))", "QM-AM with square roots.")
add(O, "o_cubes_zero_sum", "(a b c : ℝ) (h : a + b + c = 0) : a ^ 3 + b ^ 3 + c ^ 3 = 3 * a * b * c", "Classic identity.")
add(O, "o_min_x2_recip", "(x : ℝ) (hx : 0 < x) : 47 / 25 ≤ x ^ 2 + 1 / x", "Tight bound: true minimum is 3·2^(-2/3) ≈ 1.8899.")
add(O, "o_div_9", "(n : ℕ) : 9 ∣ 4 ^ n + 15 * n - 1", "Induction divisibility.")
add(O, "o_div_64", "(n : ℕ) : 64 ∣ 9 ^ n - 8 * n - 1", "Binomial expansion of (1+8)^n.")
add(O, "o_div_133", "(n : ℕ) : 133 ∣ 11 ^ (n + 2) + 12 ^ (2 * n + 1)", "Classic: 144 ≡ 11 mod 133.")
add(O, "o_imo1959_p1", "(n : ℕ) : Nat.gcd (21 * n + 4) (14 * n + 3) = 1", "IMO 1959 P1.")
add(O, "o_diff_sq_17", "(x y : ℕ) (h : x ^ 2 = y ^ 2 + 17) : x = 9 ∧ y = 8", "Factor x² - y².")
add(O, "o_square_n", "(n k : ℕ) (h : n ^ 2 + 2 * n + 12 = k ^ 2) : n = 4", "Complete the square and factor 11.")
add(O, "o_two_pow_three_pow", "(m n : ℕ) (h : 2 ^ m + 1 = 3 ^ n) : (m = 1 ∧ n = 1) ∨ (m = 3 ∧ n = 2)", "Catalan-type equation, small case.")
add(O, "o_floor_sqrt", "(n : ℕ) : ⌊Real.sqrt n + Real.sqrt (n + 1)⌋ = ⌊Real.sqrt (4 * n + 2)⌋", "Classic floor identity; hard.")
add(O, "o_hermite2", "(x : ℝ) : ⌊x⌋ + ⌊x + 1 / 2⌋ = ⌊2 * x⌋", "Hermite's identity, n = 2.")
add(O, "o_rec_linear", "(a : ℕ → ℝ) (h0 : a 0 = 1) (h : ∀ n, a (n + 1) = 2 * a n + 1) : ∀ n, a n = 2 ^ (n + 1) - 1", "Solve a recurrence.")
add(O, "o_rec_second", "(a : ℕ → ℤ) (h0 : a 0 = 0) (h1 : a 1 = 1) (h : ∀ n, a (n + 2) = 3 * a (n + 1) - 2 * a n) : ∀ n, a n = 2 ^ n - 1", "Second-order recurrence; strong induction.")
add(O, "o_poly_coeffs", "(a b : ℝ) (h : ∀ x : ℝ, x ^ 2 + a * x + b = (x - 1) * (x - 2)) : a = -3 ∧ b = 2", "Compare values at chosen points.")
add(O, "o_vieta_cubes", "(x y : ℝ) (h1 : x + y = 5) (h2 : x * y = 6) : x ^ 3 + y ^ 3 = 35", "Symmetric functions.")
add(O, "o_complex_sqrt_neg1", "(z : ℂ) (h : z ^ 2 = -1) : z = Complex.I ∨ z = -Complex.I", "Roots of z² + 1.")
add(O, "o_complex_norm", ": ‖(1 + Complex.I) ^ 10‖ = 32", "|1+i| = √2.")
add(O, "o_trig_quartic", "(x : ℝ) : Real.sin x ^ 4 + Real.cos x ^ 4 = 1 - 2 * Real.sin x ^ 2 * Real.cos x ^ 2", "Pythagorean identity squared.")
add(O, "o_cos36_cos72", ": Real.cos (Real.pi / 5) - Real.cos (2 * Real.pi / 5) = 1 / 2", "Golden-ratio trig; hard.")
add(O, "o_titu", "(a b c : ℝ) (ha : 0 < a) (hb : 0 < b) (hc : 0 < c) : a + b + c ≤ a ^ 2 / b + b ^ 2 / c + c ^ 2 / a", "Titu / Engel form.")
add(O, "o_sq_sum_third", "(a b c : ℝ) (h : a + b + c = 1) : 1 / 3 ≤ a ^ 2 + b ^ 2 + c ^ 2", "QM-AM.")
add(O, "o_recip_sum3", "(a b c : ℝ) (ha : 0 < a) (hb : 0 < b) (hc : 0 < c) (h : a + b + c = 3) : 3 ≤ 1 / a + 1 / b + 1 / c", "HM-AM, three terms.")
add(O, "o_imo1995_p2", "(a b c : ℝ) (ha : 0 < a) (hb : 0 < b) (hc : 0 < c) (h : a * b * c = 1) : 3 / 2 ≤ 1 / (a ^ 3 * (b + c)) + 1 / (b ^ 3 * (c + a)) + 1 / (c ^ 3 * (a + b))", "IMO 1995 P2; very hard.")
add(O, "o_n_dvd_2n_sub1", "(n : ℕ) (h : 0 < n) (hd : n ∣ 2 ^ n - 1) : n = 1", "Smallest prime factor and order argument; hard.")
add(O, "o_prime_sq_add2", "(p : ℕ) (hp : p.Prime) (h : (p ^ 2 + 2).Prime) : p = 3", "Mod 3 argument.")
add(O, "o_prime_triplet", "(p : ℕ) (hp : p.Prime) (h1 : (p + 2).Prime) (h2 : (p + 4).Prime) : p = 3", "One of p, p+2, p+4 is divisible by 3.")
add(O, "o_count_3_or_5", ": ((range 1001).filter (fun n => 3 ∣ n ∨ 5 ∣ n)).card = 468", "Inclusion-exclusion (computation).")
add(O, "o_vandermonde_sq", "(n : ℕ) : ∑ k ∈ range (n + 1), (n.choose k) ^ 2 = (2 * n).choose n", "Vandermonde special case.", True)
add(O, "o_sum_k_choose", "(n : ℕ) : ∑ k ∈ range (n + 1), k * n.choose k = n * 2 ^ (n - 1)", "Absorption identity.")
add(O, "o_primes_3mod4", ": ∀ N : ℕ, ∃ p, N < p ∧ p.Prime ∧ p % 4 = 3", "Infinitely many primes ≡ 3 mod 4.")
add(O, "o_ab_bc_ca_le", "(a b c : ℝ) (ha : 0 ≤ a) (hb : 0 ≤ b) (hc : 0 ≤ c) (h : a + b + c = 1) : a * b + b * c + c * a - 2 * a * b * c ≤ 7 / 27", "IMO 1984 P1 (upper half).")

assert len({l["id"] for l in L}) == len(L)
out = Path(__file__).with_name("hard100.jsonl")
out.write_text("".join(json.dumps(l, ensure_ascii=False) + "\n" for l in L))
from collections import Counter
print(len(L), Counter(l["tier"] for l in L))
